contract TokenFactory is BondingCurve, OwnableUpgradeable  {
    enum TokenState {
        NOT_CREATED,
        FUNDING,
        TRADING
    }
    uint256 public constant MAX_SUPPLY = 1 * 10 ** 9 * 10 ** 18;
    uint256 public constant INITIAL_SUPPLY = (MAX_SUPPLY * 1) / 5;
    uint256 public constant FUNDING_SUPPLY = (MAX_SUPPLY * 4) / 5;
//    uint256 public FUNDING_GOAL = 69000 ether;
//    uint256 public a = 6436789325503;
//    uint256 public b = 5000000000;
    uint256 public FUNDING_GOAL;
    uint256 public a;
    uint256 public b;
    mapping(address => TokenState) public tokens;
    mapping(address => uint256) public collateral;
    address public tokenImplementation;
    address public lpAddr;

    uint256 public tokenCount;
    mapping(uint256 => address) public tokenList;

    address public UNISWAP_V2_ROUTER ;

    uint256 public FEE_PERCENT;

    uint256 public FEE;

    function initialize(address _router, address _tokenImplementation, uint256 _feePercent, uint256 _funding, uint256 _a, uint256 _b, address _lp) initializer external {
        __Ownable_init();

        UNISWAP_V2_ROUTER = _router;
        tokenImplementation = _tokenImplementation;

        FEE_PERCENT = _feePercent;

        FUNDING_GOAL = _funding;
        a = _a;
        b = _b;

        lpAddr = _lp;
    }

    function createToken(
        string memory name,
        string memory symbol
    ) public returns (address) {
        Token token = new Token();
        token.initialize(name, symbol, MAX_SUPPLY);

		address tokenAddress = address(token);

        tokens[tokenAddress] = TokenState.FUNDING;

        tokenList[tokenCount] = tokenAddress;
        tokenCount++;

        return tokenAddress;
    }

    function buyTokens(address tokenAddress) external payable {
        require(tokens[tokenAddress] == TokenState.FUNDING, "Token not found");
        require(msg.value > 0, "ETH not enough");

        uint256 buyFee = calculateFee(msg.value, FEE_PERCENT);
        uint256 valueToBuy = msg.value - buyFee;

        FEE += buyFee;

        Token token = Token(tokenAddress);
        // TODO: convert collateral[tokenAddress] to memory
        // TODO: Add reentrancy check
        if(collateral[tokenAddress] + valueToBuy > FUNDING_GOAL) {
            valueToBuy = FUNDING_GOAL - collateral[tokenAddress];
        }
        uint256 amount = getAmountOut(a, b, token.totalSupply() - token.balanceOf(address(this)), valueToBuy);
        uint256 availableSupply = FUNDING_SUPPLY - (token.totalSupply() - token.balanceOf(address(this)));
        require(amount <= availableSupply, "Token not enough");
        collateral[tokenAddress] += valueToBuy;
        token.transfer(msg.sender, amount);
        // when reach FUNDING_GOAL
        if (collateral[tokenAddress] >= FUNDING_GOAL) {

            uint256 liquidity = addLiquidity(
                tokenAddress,
                INITIAL_SUPPLY,
                collateral[tokenAddress]
            );

            collateral[tokenAddress] = 0;
            tokens[tokenAddress] = TokenState.TRADING;

            //clear token balance
            if(token.balanceOf(address(this)) > 0 ){
                token.transfer(0x000000000000000000000000000000000000dEaD, token.balanceOf(address(this)));
            }
        }
        if (valueToBuy + buyFee < msg.value) {
            (bool success, ) = msg.sender.call{value: msg.value-valueToBuy - buyFee}(new bytes(0));
            require(success, "ETH send failed");
        }
    }

    function sellTokens(address tokenAddress, uint256 amount) external {
        require(tokens[tokenAddress] == TokenState.FUNDING, "Token not found");
        require(amount > 0, "Token not enough");
        Token token = Token(tokenAddress);
        token.transferFrom(msg.sender, address(this) , amount);
        uint256 ethAmount = getFundsNeeded(a, b, token.totalSupply()-token.balanceOf(address(this)), amount);

        uint256 sellFee = calculateFee(ethAmount, FEE_PERCENT);
        FEE += sellFee;

        collateral[tokenAddress] -= ethAmount;

        uint256 receivedETH = ethAmount - sellFee;
        // send ether
        (bool success, ) = msg.sender.call{value: receivedETH}(new bytes(0));
        require(success, "ETH send failed");
    }

    function addLiquidity(
        address tokenAddress,
        uint256 tokenAmount,
        uint256 ethAmount
    ) internal returns (uint256) {
        Token token = Token(tokenAddress);
        IUniswapV2Router02 router = IUniswapV2Router02(UNISWAP_V2_ROUTER);
        token.approve(UNISWAP_V2_ROUTER, tokenAmount);

        (, , uint256 liquidity) = router.addLiquidityETH{value: ethAmount}(
            tokenAddress,
            false,
            tokenAmount,
            0,
            0,
            lpAddr,
            block.timestamp + 10 minutes
        );
        return liquidity;
    }

    function calculateFee(uint256 amount, uint256 feePercent) internal pure returns (uint256) {
        return (amount * feePercent) / 100;
    }

    function setFundingGoal(uint256 _fundingGoal) external onlyOwner {
        FUNDING_GOAL = _fundingGoal;
    }

    function setFeePercent(uint256 feePercent) external onlyOwner {
        FEE_PERCENT = feePercent;
    }

    function setab(uint256 _a, uint256 _b) external onlyOwner {
        a = _a;
        b = _b;
    }

    function withdrawToken(address _lp,uint256 _amt) external onlyOwner {
        IERC20Upgradeable(_lp).transfer(msg.sender, _amt);
    }

    function withdrawEth(uint256 _amt) external onlyOwner {
        payable(msg.sender).transfer(_amt);
    }

}
